const {chromium}=require('playwright-core');
const assert=require('node:assert/strict'),fs=require('node:fs'),crypto=require('node:crypto');
const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEElEQVR4nGNgaPj/H4xhDABS0gn5PEa22gAAAABJRU5ErkJggg==','base64');
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 try{
  const page=await browser.newPage({viewport:{width:1440,height:1100},acceptDownloads:true}),errors=[];page.setDefaultTimeout(12000);page.on('pageerror',e=>errors.push(e.message));page.on('dialog',d=>d.accept());
  await page.goto(process.env.PREVIEW_URL||'http://127.0.0.1:8000');
  const state=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('skycrm-web-preview-v1')));
  const pasteImage=async(name,bytes)=>page.evaluate(({name,base64})=>{const data=new DataTransfer();data.items.add(new File([Uint8Array.from(atob(base64),c=>c.charCodeAt(0))],name,{type:'image/png'}));document.querySelector('#memo-content').dispatchEvent(new ClipboardEvent('paste',{clipboardData:data,bubbles:true,cancelable:true}));},{name,base64:bytes.toString('base64')});
  const width=key=>page.locator(`.crm-table col[data-column="${key}"]`).evaluate(e=>e.getBoundingClientRect().width);
  const resize=async(key,delta)=>{const r=await page.locator(`[data-resize-column="${key}"]`).boundingBox();await page.mouse.move(r.x+r.width/2,r.y+r.height/2);await page.mouse.down();await page.mouse.move(r.x+r.width/2+delta,r.y+r.height/2,{steps:12});await page.mouse.up()};
  assert.equal(await page.locator('[data-resize-column]').count(),7);const before=await width('content'),nameBefore=await width('name');await resize('content',-120);assert.ok(Math.abs((await width('content'))-(before-120))<2);assert.ok(Math.abs((await width('name'))-nameBefore)<2);assert.equal(await page.locator('[data-sort=content]').textContent(),'통화내용');
  await page.reload();assert.ok(Math.abs((await width('content'))-(before-120))<2);await page.locator('[data-tab=clients]').click();const phone2Before=await width('phone2');await resize('phone2',60);await page.locator('[data-resize-column=phone2]').focus();await page.keyboard.press('ArrowRight');assert.ok(Math.abs((await width('phone2'))-(phone2Before+68))<2);await page.locator('[data-tab=calls]').click();assert.ok(Math.abs((await width('content'))-(before-120))<2);
  await page.locator('[data-tab=memos]').click();await page.locator('[data-new-kind=note]').click();await page.locator('#memo-name').fill('파일과 이미지');await page.locator('#memo-content').fill('before after');const memo=(await state()).memos[0].id,first=(await state()).memos[0].pages[0].id;
  assert.equal(await page.locator('#background-opacity').count(),0);
  await page.locator('#memo-content').focus();await page.keyboard.press('Control+Home');for(let i=0;i<7;i++)await page.keyboard.press('ArrowRight');
  assert.equal(await page.locator('#insert-image,#image-input').count(),0);await pasteImage('작은 이미지.png',png);
  await page.waitForFunction(()=>document.querySelector('img.skycrm-local-image')?.dataset.assetLoaded==='true');
  const imageId=(await state()).memos[0].pages[0].delta.ops.find(op=>op.insert?.localImage).insert.localImage.id;
  assert.equal(await page.evaluate(()=>richEditor.getIndex(Quill.find(document.querySelector('.skycrm-local-image')))),7);assert.equal(await page.evaluate(()=>readRichText()),'before after');assert.equal(await page.locator('.skycrm-local-image').evaluate(img=>img.naturalWidth),2);assert.ok(!(await state()).memos[0].pages[0].delta.ops.some(op=>typeof op.insert==='string'&&op.insert.includes('blob:')));
  // Search/replace offsets after an inline image must remain correct.
  await page.locator('#memo-content').focus();await page.keyboard.press('Control+f');await page.locator('#find-text').fill('after');await page.locator('[data-tool=find]').click();assert.equal(await page.evaluate(()=>richSelection.index),8);await page.locator('#replace-text').fill('AFTER');await page.locator('[data-tool=replace]').click();assert.equal(await page.evaluate(()=>readRichText()),'before AFTER');assert.equal(await page.locator('.skycrm-local-image').count(),1);await page.keyboard.press('Escape');await page.locator('#memo-content').focus();await page.keyboard.press('Control+z');assert.equal(await page.evaluate(()=>readRichText()),'before after');assert.equal(await page.locator('.skycrm-local-image').count(),1);
  const bytes=Buffer.alloc(1024*1024,0x41),small=Buffer.from('첨부파일 다운로드 검증\n','utf8');
  await page.locator('#attachment-input').setInputFiles([{name:'보고서.txt',mimeType:'text/plain',buffer:small},{name:'자료.bin',mimeType:'application/octet-stream',buffer:bytes}]);
  await page.waitForFunction(()=>document.querySelectorAll('[data-download-asset]').length===2);const attached=(await state()).memos[0].pages[0].attachments;
  assert.ok((await page.evaluate(()=>localStorage.getItem('skycrm-web-preview-v1').length))<20000,'file bytes must not fill localStorage');
  const downloadPromise=page.waitForEvent('download');await page.locator(`[data-download-asset="${attached[1].id}"]`).click();const download=await downloadPromise;assert.equal(download.suggestedFilename(),'자료.bin');assert.equal(crypto.createHash('sha256').update(fs.readFileSync(await download.path())).digest('hex'),crypto.createHash('sha256').update(bytes).digest('hex'));
  await page.reload();await page.locator('[data-tab=memos]').click();await page.locator(`[data-memo-edit="${memo}"]`).click();await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal(await page.locator('[data-download-asset]').count(),2);assert.ok((await page.locator('.skycrm-local-image').getAttribute('src')).startsWith('blob:'));
  const reloadDownloadPromise=page.waitForEvent('download');await page.locator(`[data-download-asset="${attached[0].id}"]`).click();const reloadDownload=await reloadDownloadPromise;assert.equal(fs.readFileSync(await reloadDownload.path(),'utf8'),small.toString('utf8'));
  await page.locator('[data-add-page]').click();await page.locator('#memo-content').fill('second');assert.equal(await page.locator('[data-download-asset],.skycrm-local-image').count(),0);const second=(await state()).memos[0].activePageId;
  await pasteImage('둘째.png',png);await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');const secondImage=(await state()).memos[0].pages[1].delta.ops.find(op=>op.insert?.localImage).insert.localImage.id;
  await page.locator(`[data-page-id="${first}"]`).click();await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal(await page.locator('[data-download-asset]').count(),2);
  await page.locator(`[data-remove-asset="${attached[0].id}"]`).click();await page.waitForFunction(async id=>(await getAsset(id))===null,attached[0].id);assert.ok(await page.evaluate(async id=>!!(await getAsset(id))?.blob,attached[1].id));
  await page.locator(`[data-delete-page="${first}"]`).click();await page.waitForFunction(async ids=>(await Promise.all(ids.map(getAsset))).every(x=>x===null),[imageId,attached[1].id]);assert.ok(await page.evaluate(async id=>!!(await getAsset(id))?.blob,secondImage));assert.equal((await state()).memos[0].activePageId,second);
  // Screenshot-style image paste uses the same durable image storage.
  await page.locator('#memo-content').focus();await page.evaluate(encoded=>{const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),data=new DataTransfer();data.items.add(new File([bytes],'붙여넣기.png',{type:'image/png'}));document.querySelector('#memo-content').dispatchEvent(new ClipboardEvent('paste',{clipboardData:data,bubbles:true,cancelable:true}));},png.toString('base64'));
  await page.waitForFunction(()=>document.querySelectorAll('.skycrm-local-image[data-asset-loaded=true]').length===2);
  await pasteImage('잘못된 이미지.png',Buffer.from('not an image'));await page.waitForFunction(()=>document.querySelector('#status').textContent.includes('이미지를 읽지'));assert.equal(await page.locator('.skycrm-local-image').count(),2);
  // Metadata saving failure must roll back the file and leave existing images intact.
  await page.evaluate(()=>{window.savedSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){if(key==='skycrm-web-preview-v1')throw new DOMException('QuotaExceeded','QuotaExceededError');return window.savedSetItem.call(this,key,value)}});
  await page.locator('#attachment-input').setInputFiles({name:'실패하면 남지 않는 파일.txt',mimeType:'text/plain',buffer:small});await page.waitForFunction(()=>document.querySelector('#status').textContent.includes('파일 추가를 취소'));assert.equal(await page.locator('[data-download-asset]').count(),0);await page.evaluate(()=>{Storage.prototype.setItem=window.savedSetItem});
  const orphan=await page.evaluate(async()=>{const db=await openAssetDatabase();return new Promise(resolve=>{const r=db.transaction('files','readonly').objectStore('files').getAll();r.onsuccess=()=>resolve(r.result.some(a=>a.name==='실패하면 남지 않는 파일.txt'))})});assert.equal(orphan,false);assert.equal(await page.locator('.skycrm-local-image').count(),2);
  await page.reload();await page.locator('[data-tab=memos]').click();await page.locator(`[data-memo-edit="${memo}"]`).click();await page.waitForFunction(()=>document.querySelectorAll('.skycrm-local-image[data-asset-loaded=true]').length===2);assert.equal(await page.evaluate(()=>readRichText()),'second');assert.deepEqual(errors,[]);
  console.log('PASS Chromium: pointer/keyboard column resize and independent persisted widths, opaque background UI, caret-position inline images, image-aware search/replace/undo, IndexedDB attachments, byte-exact downloads after reload, page isolation/deletion cleanup, image paste, invalid file handling and quota rollback');
 }finally{await browser.close();}
})().catch(error=>{console.error(error);process.exit(1)});
